ruleToc.nextTocUrl:
text.下一页@href
@js:
var next=[],url=result[0],
regex=/第\d+.(\d+)页.当前\d+条.页/;
yes=src.match(regex);
page=yes&&yes[1];
if(page){
	for(i=2;i<=page;i++){
		link=String(url).replace(/_\d+/,"_"+i);
		next.push(link)
		}
	}else next=url;
next;

